class CardioActivity extends DataClass implements Insertable<CardioActivity> {
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String id;

  /// strava | health_connect | manual
  final String source;
  final String? externalId;
  final String? name;

  /// run | walk | ride | hike | other (normalised)
  final String sportType;
  final DateTime startAt;
  final String localDate;
  final String? tzName;
  final double? distanceM;
  final int? movingTimeS;
  final int? elapsedTimeS;
  final double? elevationGainM;
  final double? avgHeartRate;
  final double? maxHeartRate;
  final double? avgSpeedMps;
  final double? calories;

  /// JSON list of per-km splits:
  /// [{"distance_m":..,"moving_time_s":..,"avg_hr":..,"elev_diff_m":..}]
  final String? splitsJson;
  final String? lapsJson;
  final String? rawJson;

  /// When the record was last fetched from its provider (Strava cache rule).
  final DateTime fetchedAt;
  const CardioActivity({
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.id,
    required this.source,
    this.externalId,
    this.name,
    required this.sportType,
    required this.startAt,
    required this.localDate,
    this.tzName,
    this.distanceM,
    this.movingTimeS,
    this.elapsedTimeS,
    this.elevationGainM,
    this.avgHeartRate,
    this.maxHeartRate,
    this.avgSpeedMps,
    this.calories,
    this.splitsJson,
    this.lapsJson,
    this.rawJson,
    required this.fetchedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['id'] = Variable<String>(id);
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || externalId != null) {
      map['external_id'] = Variable<String>(externalId);
    }
    if (!nullToAbsent || name != null) {
      map['name'] = Variable<String>(name);
    }
