      map['completed_at'] = Variable<DateTime>(completedAt);
    }
    if (!nullToAbsent || carriedFromDate != null) {
      map['carried_from_date'] = Variable<String>(carriedFromDate);
    }
    if (!nullToAbsent || project != null) {
      map['project'] = Variable<String>(project);
    }
    return map;
  }

